# ---- field arithmetic: GF(2^128), x^128 + x^7 + x^2 + x + 1 -------------------
_MASK = (1 << 128) - 1
_RED = 0x87                       # x^7 + x^2 + x + 1


def _mul(x: int, y: int) -> int:
    """Carry-less multiply, right-shift representation."""
    z, v = 0, y
    for i in range(128):
        if (x >> (127 - i)) & 1:
            z ^= v
        v = (v >> 1) ^ (0xE1 << 120) if v & 1 else v >> 1
    return z


def _shl(v: int, n: int) -> int:
    v <<= n
    return (v & _MASK) ^ (_RED * (v >> 128))


def _tables(h: int) -> list[list[int]]:
    """tables[j][n] = H * x^(4j) * n  ->  GHASH in 32 steps per block."""
